#!/usr/bin/env bash
# Activate Emscripten 4.0.23 (emsdk_env.sh) before running.
set -euo pipefail
output=$(cd -- "$(dirname -- "$0")" && pwd)
build=$(mktemp -d)
trap 'rm -rf "$build"' EXIT
cd "$build"
export LC_ALL=C
jobs=${JOBS:-4}

download() {
  local url=$1 sha=$2 file=${1##*/}
  curl --fail --silent --show-error --location --retry 3 "$url" -o "$file"
  echo "$sha  $file" | sha256sum --check
  tar -xf "$file"
}

download https://www.libarchive.org/downloads/libarchive-3.8.11.tar.xz a3dc0872b1b39da34dc18ef1b944f0f11ffd37425d70ae04be679279f1cf43d2
download https://tukaani.org/xz/xz-5.8.3.tar.xz fff1ffcf2b0da84d308a14de513a1aa23d4e9aa3464d17e64b9714bfdd0bbfb6
download https://github.com/facebook/zstd/releases/download/v1.5.7/zstd-1.5.7.tar.gz eb33e51f49a15e023950cd7825ca74a4a2b43db8354825ac24fc1b7ee09e6fa3
download https://github.com/lz4/lz4/releases/download/v1.10.0/lz4-1.10.0.tar.gz 537512904744b35e232912055ccf8ec66d768639ff3abe5788d90d792ec5f48b
download https://sourceware.org/pub/bzip2/bzip2-1.0.8.tar.gz ab5a03176ee106d3f0fa90e381da478ddae405918153cca248e682cd0c4a2269
download https://github.com/madler/zlib/releases/download/v1.3.2/zlib-1.3.2.tar.gz bb329a0a2cd0274d05519d61c667c062e06990d72e125ee2dfa8de64f0119d16

prefix="$build/deps"
mkdir -p "$prefix/include" "$prefix/lib"
export CC=emcc AR=emar RANLIB=emranlib CFLAGS="-O2"
host=wasm32-unknown-emscripten

(cd xz-5.8.3 && ./configure --host="$host" --prefix="$prefix" --disable-shared \
  --disable-threads --disable-xz --disable-xzdec --disable-lzmadec \
  --disable-lzmainfo --disable-scripts --disable-doc --disable-nls && make -j"$jobs" install)
(cd zlib-1.3.2 && ARFLAGS=rc ./configure --static --prefix="$prefix" && make -j"$jobs" install)
(cd bzip2-1.0.8 && make -j"$jobs" CC=emcc AR=emar RANLIB=emranlib CFLAGS=-O2 libbz2.a)
cp bzip2-1.0.8/bzlib.h "$prefix/include/"
cp bzip2-1.0.8/libbz2.a "$prefix/lib/"
make -C zstd-1.5.7/lib -j"$jobs" libzstd.a ZSTD_LIB_COMPRESSION=0 \
  ZSTD_LIB_DEPRECATED=0 ZSTD_LIB_DICTBUILDER=0 ZSTD_LEGACY_SUPPORT=0 ZSTD_NO_ASM=1
cp zstd-1.5.7/lib/{zstd.h,zstd_errors.h} "$prefix/include/"
cp zstd-1.5.7/lib/libzstd.a "$prefix/lib/"
make -C lz4-1.10.0/lib -j"$jobs" liblz4.a
cp lz4-1.10.0/lib/{lz4.h,lz4hc.h,lz4frame.h} "$prefix/include/"
cp lz4-1.10.0/lib/liblz4.a "$prefix/lib/"

(cd libarchive-3.8.11 && \
  CPPFLAGS="-I$prefix/include" LDFLAGS="-L$prefix/lib" \
    ./configure --host="$host" --disable-shared --disable-bsdtar --disable-bsdcat \
    --disable-bsdcpio --disable-bsdunzip --disable-xattr --disable-acl \
    --without-openssl --without-md --without-libb2 --without-xml2 --without-expat \
    --without-libiconv-prefix && make -j"$jobs" libarchive.la)
for codec in ICONV BZLIB_H LIBLZ4 LIBLZMA LIBZ LIBZSTD; do
  grep -qx "#define HAVE_$codec 1" libarchive-3.8.11/config.h
done

printf '%s\n' '/* Generated by Emscripten. Rebuild with ./rebuild.sh. */' '/* oxlint-disable */' > generated-header.js
emcc -O2 --no-entry -Ilibarchive-3.8.11/libarchive "$output/reader.c" \
  libarchive-3.8.11/.libs/libarchive.a -L"$prefix/lib" -llzma -llz4 -lzstd -lbz2 -lz \
  -sMODULARIZE -sENVIRONMENT=worker -sFILESYSTEM=0 -sALLOW_MEMORY_GROWTH \
  -sMAXIMUM_MEMORY=536870912 -sEXPORTED_RUNTIME_METHODS=UTF8ToString,HEAPU8 \
  -sINCOMING_MODULE_JS_API=locateFile,wasmBinary --extern-pre-js generated-header.js \
  -o libarchive.mjs
install -m 644 libarchive.mjs libarchive.wasm "$output/"
(cd "$output" && pnpm exec oxfmt libarchive.mjs)
